const s           = (v) => (v === undefined || v === null) ? "" : String(v).trim();
const stripSpaces = (v) => s(v).replace(/\s+/g, " ");
const digitsOnly  = (v) => s(v).replace(/\D/g, "");
const upperNoSpace = (v) => s(v).toUpperCase().replace(/\s+/g, "");
function truthy(v) {
  const t = String(v ?? "").trim().toLowerCase();
  return ["true","1","on","yes","y","si","sí","checked"].includes(t);
}

