const Email    = s(data.Email).toLowerCase();
const PhoneRaw = s(data.Phone);
const Company  = stripSpaces(data.Company);
const DNIraw   = s(data.DNI);
const Checkbox = data.checkbox;

const utm = {
  utm_source:   s(data.utm_source),
  utm_medium:   s(data.utm_medium),
  utm_campaign: s(data.utm_campaign),
  utm_content:  s(data.utm_content),
  utm_term:     s(data.utm_term),
  utm_country:  s(data.utm_country),
};

// =====================================================
// 🛑 BLOQUE 1 — SEÑALES DE ROBOT
// =====================================================
const tieneFormData = Name || Email || PhoneRaw || Company || DNIraw;
if (!tieneFormData) return [];

if (httpMethod === "GET" && ctx.query) return [];
if (httpMethod && httpMethod !== "POST") return [];
if (String(data.website || "").trim() !== "") return [];

const now       = Date.now();
const formStart = Number(data.form_start_ts || 0);
if (formStart && (now - formStart) < 3000) return [];

