// 🛑 BLOQUE 2 — INYECCIÓN EN CUALQUIER CAMPO
// (SQL injection, XSS, shell commands)
// =====================================================
const sqlPattern    = /('|--|;|\/\*|\*\/|xp_|UNION\s+SELECT|DROP\s+TABLE|INSERT\s+INTO|SELECT\s+\*)/i;
const scriptPattern = /(javascript:|<script|<\/script|onerror=|onload=|eval\(|alert\()/i;
const shellPattern  = /(\$\(|`[^`]+`|&&\s*(rm|cat|wget|curl)|;\s*(rm|cat|wget))/i;

const allFields = [Name, Email, Company, DNIraw];
for (const field of allFields) {
  if (sqlPattern.test(field) || scriptPattern.test(field) || shellPattern.test(field)) return [];
}

