// 🛑 BLOQUE 3 — NOMBRE SPAM
// =====================================================
// Patrones de contenido spam en nombre
const urlPattern          = /(https?:\/\/|www\.|[a-z0-9-]+\.(com|net|org|ru|xyz|info|io))/i;
const htmlPattern         = /<[a-z][\s\S]*>/i;
const emojiPattern        = /[\uD800-\uDBFF][\uDC00-\uDFFF]/;         // surrogate pairs, sin /u
const cyrillicPattern     = /[\u0400-\u04FF]/;                         // cirílico (ххх, etc.)
const spamKeywords        = /(payment|available|earn|free money|click here|prize|hs=|crypto|bitcoin|\$\d)/i;
const nombreHumanoPattern = /^[a-zA-ZÀ-ÿÑñ\s'.-]{3,}$/;

