  urlPattern.test(Name)          ||
  htmlPattern.test(Name)         ||
  emojiPattern.test(Name)        ||
  cyrillicPattern.test(Name)     ||
  spamKeywords.test(Name)        ||
  !nombreHumanoPattern.test(Name)
)) return [];

