  "mailbox.in.ua","temp-mail.org","guerrillamail.com","yopmail.com",
  "trashmail.com","sharklasers.com","mailnull.com","spamgourmet.com",
  "throwam.com","dispostable.com","maildrop.cc","10minutemail.com",
  "fakeinbox.com","mailinator.com","tempmail.com","getnada.com",
  // TLDs de alto riesgo en formularios B2B
  "mail.ru","bk.ru","inbox.ru","list.ru","ro.ru"
]);

const emailDomain = Email.includes("@") ? Email.split("@")[1].toLowerCase() : "";
if (emailDomain && spamDomains.has(emailDomain)) return [];

// Detectar cirílico también en el email
if (cyrillicPattern.test(Email)) return [];

// =====================================================
// 🛑 BLOQUE 5 — DNI SIN DÍGITOS
// =====================================================
const dniDigits = digitsOnly(DNIraw);
if (DNIraw && dniDigits.length === 0) return [];

// =====================================================
// 🛑 BLOQUE 6 — TELÉFONO INVÁLIDO
// =====================================================
const PhoneLocal = digitsOnly(PhoneRaw);
const phoneClean = PhoneRaw.replace(/[^\d+]/g, "");

const looksEcuadorLocal  = (PhoneLocal.length >= 9 && PhoneLocal.length <= 10 && PhoneLocal.startsWith("0"));
const looksEcuadorE164   = phoneClean.startsWith("+593");
const looksInternational = phoneClean.startsWith("+") && E164_RE.test(phoneClean);

// Teléfono que no es Ecuador ni E.164 internacional válido → bloqueado
if (PhoneRaw && !looksEcuadorLocal && !looksEcuadorE164 && !looksInternational) return [];

