  return [{ json: { status: "INVALID", reason: "invalid_name_length", Name } }];
}
if (!NAME_RE.test(Name)) {
  return [{ json: { status: "INVALID", reason: "invalid_name_format", Name } }];
}

if (!EMAIL_RE.test(Email) || Email.length > 120) {
  return [{ json: { status: "INVALID", reason: "invalid_email", Email } }];
}

if (Company.length < 2 || Company.length > 120) {
  return [{ json: { status: "INVALID", reason: "invalid_company_length", Company } }];
}

if ((phoneClean.match(/\+/g) || []).length > 1) {
  return [{ json: { status: "INVALID", reason: "invalid_phone_format", PhoneRaw } }];
}

