if (looksEcuadorLocal || looksEcuadorE164) {
  if (looksEcuadorE164) {
    if (!E164_RE.test(phoneClean)) {
      return [{ json: { status: "INVALID", reason: "invalid_phone_ecuador_e164", PhoneRaw } }];
    }
    PhoneNormalized = phoneClean;
  } else {
    let national = PhoneLocal;
    if (national.startsWith("0")) national = national.slice(1);
    PhoneNormalized = `+593${national}`;
    if (!E164_RE.test(PhoneNormalized)) {
      return [{ json: { status: "INVALID", reason: "cannot_build_phone_e164_ecuador", PhoneRaw, PhoneNormalized } }];
    }
  }
} else if (looksInternational) {
  PhoneNormalized = phoneClean;
}

// ---- DNI: si tiene 13 dígitos → validar como RUC Ecuador ----
const dniUpper = upperNoSpace(DNIraw);

if (dniDigits.length === 13) {
  if (!/^\d{13}$/.test(dniDigits)) {
    return [{ json: { status: "INVALID", reason: "invalid_dni_ecuador_ruc", DNI: DNIraw } }];
  }
} else {
  if (DNIraw.length < 5) {
    return [{ json: { status: "INVALID", reason: "invalid_dni_min_length", DNI: DNIraw } }];
  }
}

// =====================================================
// ✅ OK — LEAD LIMPIO
// =====================================================
return [{
  json: {
    status: "VALID",
    Origen: "MVONE",
    Name,
    Email,
    Phone: PhoneLocal,
    PhoneNormalized,
    Company,
    DNI: dniUpper,
    checkbox: true,
    ...utm
  }
}];

const data = $input.first().json;

// Obtener razón social del SRI o del formulario como fallback
const razonSocial = 
  $items("Code1")?.[0]?.json?.razonSocial ?? 
  $items("Datos1")?.[0]?.json?.empresa ?? 
  "";

// Formato URL
const name = encodeURIComponent(razonSocial.trim()).replace(/%20/g, "+");

return items.map((item) => {
